import gcm_fast


class Solver:
    def solve(self, problem, **kwargs):
        key = problem["key"]
        nonce = problem["nonce"]
        plaintext = problem["plaintext"]
        associated_data = problem["associated_data"]
        if associated_data:
            ciphertext, tag = gcm_fast.encrypt(key, nonce, plaintext, associated_data)
        else:
            ciphertext, tag = gcm_fast.encrypt(key, nonce, plaintext)
        return {"ciphertext": ciphertext, "tag": tag}

