        if (has_aad) PyBuffer_Release(&aad);
        PyBuffer_Release(&key); PyBuffer_Release(&nonce); PyBuffer_Release(&pt);
        return NULL;
    }

    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    int ok = 1;
    int outl = 0, total = 0;
    if (!ctx) ok = 0;
    if (ok && EVP_EncryptInit_ex(ctx, cipher, NULL, NULL, NULL) != 1) ok = 0;
    if (ok && EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_GCM_SET_IVLEN, (int)nonce.len, NULL) != 1) ok = 0;
    if (ok && EVP_EncryptInit_ex(ctx, NULL, NULL, key.buf, nonce.buf) != 1) ok = 0;
    if (ok && has_aad && aad.len > 0) {
        if (EVP_EncryptUpdate(ctx, NULL, &outl, aad.buf, (int)aad.len) != 1) ok = 0;
    }
    if (ok && pt.len > 0) {
        if (EVP_EncryptUpdate(ctx, (unsigned char *)PyBytes_AS_STRING(ct_obj), &outl,
                              pt.buf, (int)pt.len) != 1) ok = 0;
        total = outl;
    }
    if (ok && EVP_EncryptFinal_ex(ctx, (unsigned char *)PyBytes_AS_STRING(ct_obj) + total, &outl) != 1) ok = 0;
    total += outl;
    if (ok && EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_GCM_GET_TAG, 16, PyBytes_AS_STRING(tag_obj)) != 1) ok = 0;

    if (ctx) EVP_CIPHER_CTX_free(ctx);
    if (has_aad) PyBuffer_Release(&aad);
    PyBuffer_Release(&key); PyBuffer_Release(&nonce); PyBuffer_Release(&pt);

    if (!ok) {
        Py_DECREF(ct_obj); Py_DECREF(tag_obj);
        PyErr_SetString(PyExc_RuntimeError, "encrypt failed");
        return NULL;
    }
    if (total != pt.len) {
        _PyBytes_Resize(&ct_obj, total);
    }
    return Py_BuildValue("NN", ct_obj, tag_obj);
}

