    dt = (now() - t0) / 3;
    printf("gcm128_encrypt_ctr32: %.4f s  %.1f MB/s\n", dt, (bytes/1e6)/dt);
    unsigned char tag[16];
    CRYPTO_gcm128_tag(g, tag, 16);
    printf("tag %02x%02x\n", tag[0], tag[1]);
