#include <stdio.h>
#include <stdint.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <omp.h>
#include <openssl/aes.h>

extern void aesni_set_encrypt_key(const unsigned char *userKey, int bits, AES_KEY *key);
extern void aesni_ctr32_encrypt_blocks(const unsigned char *in, unsigned char *out,
                                       size_t blocks, const AES_KEY *key, const unsigned char ivec[16]);

static double now() {
    struct timespec ts;
    clock_gettime(CLOCK_MONOTONIC, &ts);
    return ts.tv_sec + ts.tv_nsec * 1e-9;
}

static void store_be32(unsigned char *p, uint32_t v) {
    p[0] = (unsigned char)(v >> 24);
    p[1] = (unsigned char)(v >> 16);
    p[2] = (unsigned char)(v >> 8);
    p[3] = (unsigned char)v;
}

int main(int argc, char **argv) {
    int threads = argc > 1 ? atoi(argv[1]) : 4;
    omp_set_num_threads(threads);
    unsigned char keyb[16];
    memset(keyb, 1, 16);
    AES_KEY key;
    aesni_set_encrypt_key(keyb, 128, &key);

    size_t bytes = 60000ull * 1024;
    size_t blocks = bytes / 16;
    unsigned char *in = aligned_alloc(64, bytes);
    unsigned char *out = aligned_alloc(64, bytes);
    memset(in, 0x5a, bytes);

    int nthreads = threads;
    size_t per = (blocks + nthreads - 1) / nthreads;

    double t0 = now();
    int N = 4;
    for (int iter = 0; iter < N; iter++) {
        #pragma omp parallel
        {
            int tid = omp_get_thread_num();
            int nth = omp_get_num_threads();
            size_t start = (size_t)tid * per;
            size_t end = start + per;
            if (end > blocks) end = blocks;
            if (start < blocks) {
                unsigned char iv[16];
                memset(iv, 0, 12);
                /* counter starts at 2 for block 0 */
                store_be32(iv + 12, (uint32_t)(2 + start));
                aesni_ctr32_encrypt_blocks(in + start * 16, out + start * 16, end - start, &key, iv);
            }
        }
    }
    double dt = (now() - t0) / N;
    printf("threads %d omp_ctr: %.4f s  %.1f MB/s\n", threads, dt, (bytes/1e6)/dt);
    free(in); free(out);
    return 0;
