static void store_be32(unsigned char *p, uint32_t v) {
    p[0] = (unsigned char)(v >> 24);
    p[1] = (unsigned char)(v >> 16);
    p[2] = (unsigned char)(v >> 8);
    p[3] = (unsigned char)v;
}

static void *worker(void *arg) {
    job_t *j = arg;
    for (;;) {
        pthread_mutex_lock(&j->mu);
        while (!j->ready && !j->stop) pthread_cond_wait(&j->cv, &j->mu);
        if (j->stop) { pthread_mutex_unlock(&j->mu); break; }
        j->ready = 0;
        pthread_mutex_unlock(&j->mu);

        unsigned char iv[16];
        memcpy(iv, j->iv_prefix, 12);
        store_be32(iv + 12, j->counter0 + (uint32_t)j->start_block);
        aesni_ctr32_encrypt_blocks(j->in + j->start_block * 16,
                                   j->out + j->start_block * 16,
                                   j->nblocks, j->key, iv);

        pthread_mutex_lock(&j->mu);
        j->done = 1;
        pthread_cond_signal(&j->cv);
        pthread_mutex_unlock(&j->mu);
    }
    return NULL;
}

int main(int argc, char **argv) {
