    unsigned char *out = aligned_alloc(64, bytes);
    memset(in, 0x5a, bytes);

    job_t jobs[MAX_T];
    pthread_t th[MAX_T];
    for (int t = 0; t < threads; t++) {
        memset(&jobs[t], 0, sizeof(jobs[t]));
        pthread_mutex_init(&jobs[t].mu, NULL);
        pthread_cond_init(&jobs[t].cv, NULL);
        pthread_create(&th[t], NULL, worker, &jobs[t]);
    }

    size_t per = (blocks + threads - 1) / threads;

    /* warmup */
    for (int iter = 0; iter < 1; iter++) {
        size_t b = 0;
        int launched = 0;
        for (int t = 0; t < threads && b < blocks; t++) {
            size_t nb = per;
            if (b + nb > blocks) nb = blocks - b;
            pthread_mutex_lock(&jobs[t].mu);
            jobs[t].in = in; jobs[t].out = out;
            jobs[t].start_block = b; jobs[t].nblocks = nb;
            jobs[t].key = &key;
            memset(jobs[t].iv_prefix, 0, 12);
            jobs[t].counter0 = 2;
            jobs[t].done = 0; jobs[t].ready = 1;
            pthread_cond_signal(&jobs[t].cv);
            pthread_mutex_unlock(&jobs[t].mu);
            b += nb; launched++;
        }
        for (int t = 0; t < launched; t++) {
            pthread_mutex_lock(&jobs[t].mu);
            while (!jobs[t].done) pthread_cond_wait(&jobs[t].cv, &jobs[t].mu);
            pthread_mutex_unlock(&jobs[t].mu);
        }
    }

    double t0 = now();
    int N = 6;
    for (int iter = 0; iter < N; iter++) {
        size_t b = 0;
        int launched = 0;
        for (int t = 0; t < threads && b < blocks; t++) {
            size_t nb = per;
            if (b + nb > blocks) nb = blocks - b;
            pthread_mutex_lock(&jobs[t].mu);
            jobs[t].in = in; jobs[t].out = out;
            jobs[t].start_block = b; jobs[t].nblocks = nb;
            jobs[t].key = &key;
            memset(jobs[t].iv_prefix, 0, 12);
            jobs[t].counter0 = 2;
            jobs[t].done = 0; jobs[t].ready = 1;
            pthread_cond_signal(&jobs[t].cv);
            pthread_mutex_unlock(&jobs[t].mu);
            b += nb; launched++;
        }
        for (int t = 0; t < launched; t++) {
            pthread_mutex_lock(&jobs[t].mu);
            while (!jobs[t].done) pthread_cond_wait(&jobs[t].cv, &jobs[t].mu);
            pthread_mutex_unlock(&jobs[t].mu);
        }
    }
    double dt = (now() - t0) / N;
    printf("pool threads %d ctr: %.4f s  %.1f MB/s\n", threads, dt, (bytes/1e6)/dt);

    /* GHASH only over ciphertext using gcm decrypt? measure ghash via encrypt of zeros? */
    /* Use CRYPTO_gcm128_encrypt on already? Let's time GHASH by calling gcm encrypt which includes both.
       Separate: encrypt_ctr32 includes ghash. Time ghash by decrypt path? 
       CRYPTO_gcm128 has no public ghash-only. Time full gcm single thread for reference. */
    GCM128_CONTEXT *g = CRYPTO_gcm128_new(&key, (block128_f)aesni_encrypt);
    unsigned char iv12[12] = {0};
    CRYPTO_gcm128_setiv(g, iv12, 12);
