    }
    dt = (now()-t0)/3;
    printf("single gcm: %.4f s %.1f MB/s\n", dt, (bytes/1e6)/dt);

    /* How fast is ghash alone? Decrypt doesn't skip ctr. 
       We can approximate by timing encrypt_ctr32 minus ctr. */
    free(in); free(out);
    return 0;
}
