{"command":"cat > bench_full.c << 'EOF'
#include <stdio.h>
#include <stdint.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>
#include <openssl/aes.h>
#include <openssl/modes.h>

extern void aesni_set_encrypt_key(const unsigned char *userKey, int bits, AES_KEY *key);
extern void aesni_encrypt(const unsigned char *in, unsigned char *out, const AES_KEY *key);
extern void aesni_ctr32_encrypt_blocks(const unsigned char *in, unsigned char *out,
                                       size_t blocks, const AES_KEY *key, const unsigned char ivec[16]);
extern void gcm_ghash_clmul(uint64_t Xi[2], const void *Htable, const uint8_t *inp, size_t len);
extern void gcm_gmult_clmul(uint64_t Xi[2], const void *Htable);

static double now() {
    struct timespec ts; clock_gettime(CLOCK_MONOTONIC, &ts);
    return ts.tv_sec + ts.tv_nsec*1e-9;
}

#define MAX_T 8

typedef struct {
    pthread_mutex_t mu;
    pthread_cond_t cv;
    int ready, done, stop;
    int kind; /* 0 = ctr, 1 = ghash */
    const unsigned char *in;
    unsigned char *out;
    size_t start_block;
    size_t nblocks;
    const AES_KEY *key;
    unsigned char iv_prefix[12];
    uint32_t counter0;
    const void *Htable;
    uint64_t Xi[2];
    const uint8_t *ghin;
    size_t ghlen;
} job_t;

static void store_be32(unsigned char *p, uint32_t v) {
    p[0]=(unsigned char)(v>>24); p[1]=(unsigned char)(v>>16);
    p[2]=(unsigned char)(v>>8); p[3]=(unsigned char)v;
}

static void *worker(void *arg) {
    job_t *j = arg;
    for (;;) {
        pthread_mutex_lock(&j->mu);
        while (!j->ready && !j->stop) pthread_cond_wait(&j->cv, &j->mu);
        if (j->stop) { pthread_mutex_unlock(&j->mu); break; }
        int kind = j->kind;
        j->ready = 0;
        pthread_mutex_unlock(&j->mu);

        if (kind == 0) {
            unsigned char iv[16];
            memcpy(iv, j->iv_prefix, 12);
            store_be32(iv+12, j->counter0 + (uint32_t)j->start_block);
            aesni_ctr32_encrypt_blocks(j->in + j->start_block*16,
                                       j->out + j->start_block*16,
                                       j->nblocks, j->key, iv);
        } else {
            j->Xi[0] = j->Xi[1] = 0;
            gcm_ghash_clmul(j->Xi, j->Htable, j->ghin, j->ghlen);
        }

        pthread_mutex_lock(&j->mu);
        j->done = 1;
        pthread_cond_signal(&j->cv);
        pthread_mutex_unlock(&j->mu);
    }
    return NULL;
}

static void post_and_wait(job_t *jobs, int n) {
    for (int t = 0; t < n; t++) {
        pthread_mutex_lock(&jobs[t].mu);
        jobs[t].done = 0;
        jobs[t].ready = 1;
        pthread_cond_signal(&jobs[t].cv);
        pthread_mutex_unlock(&jobs[t].mu);
    }
    for (int t = 0; t < n; t++) {
        pthread_mutex_lock(&jobs[t].mu);
        while (!jobs[t].done) pthread_cond_wait(&jobs[t].cv, &jobs[t].mu);
        pthread_mutex_unlock(&jobs[t].mu);
    }
}

/* multiply Xi by H^k using gmult k times — slow, only for correctness test of small k */
static void gmult_pow(uint64_t Xi[2], const void *Htable, uint64_t k) {
    /* Xi = Xi * H^k. Compute by repeated gmult — NOT for hot path. */
    for (uint64_t i = 0; i < k; i++) gcm_gmult_clmul(Xi, Htable);
}

int main(int argc, char **argv) {
    int threads = argc > 1 ? atoi(argv[1]) : 4;
    unsigned char keyb[16]; memset(keyb, 1, 16);
    AES_KEY key;
    aesni_set_encrypt_key(keyb, 128, &key);
    GCM128_CONTEXT *gctx = CRYPTO_gcm128_new(&key, (block128_f)aesni_encrypt);
    unsigned char iv12[12]; memset(iv12, 7, 12);
    CRYPTO_gcm128_setiv(gctx, iv12, 12);
    void *Htable = (unsigned char *)gctx + 0x60;

    size_t bytes = 60000ull * 1024;
    size_t blocks = bytes / 16;
    unsigned char *in = aligned_alloc(64, bytes);
    unsigned char *out = aligned_alloc(64, bytes);
    memset(in, 0x5a, bytes);

    job_t jobs[MAX_T];
    pthread_t th[MAX_T];
    for (int t = 0; t < threads; t++) {
        memset(&jobs[t], 0, sizeof(jobs[t]));
        pthread_mutex_init(&jobs[t].mu, NULL);
        pthread_cond_init(&jobs[t].cv, NULL);
        jobs[t].key = &key;
        jobs[t].Htable = Htable;
        pthread_create(&th[t], NULL, worker, &jobs[t]);
    }

    size_t per = (blocks + threads - 1) / threads;

    /* pipeline: while computing ghash of previous ciphertext, compute next CTR.
       For a single message we can overlap CTR of chunk i+1 with GHASH of chunk i
       if we do them on different threads. Simplest fast approach:
       1) parallel CTR all chunks
       2) parallel GHASH all chunks
       That's sequential phases. Target < 2.8ms. CTR pool 4 was 6.2ms, GHASH 2.9ms.
       Combined ~9ms, still 4x not 13x.
       Overlap: half threads CTR, half GHASH doesn't help a single pass.
       TRUE overlap within one message: stream. CTR produces chunk, GHASH consumes it.
       With 4 threads: 2 CTR + 2 GHASH. CTR is the slower one (6ms for all with 4 threads = 1.5ms per quarter?).
       Let's measure overlapped pipeline with chunk streaming.
    */

    /* Phase measurement: CTR then GHASH sequential with pool */
    double t0 = now();
    int N = 4;
    for (int iter = 0; iter < N; iter++) {
        size_t b = 0;
        int launched = 0;
        for (int t = 0; t < threads && b < blocks; t++) {
            size_t nb = per;
            if (b + nb > blocks) nb = blocks - b;
            jobs[t].kind = 0;
            jobs[t].in = in; jobs[t].out = out;
            jobs[t].start_block = b; jobs[t].nblocks = nb;
            memcpy(jobs[t].iv_prefix, iv12, 12);
            jobs[t].counter0 = 2;
            b += nb; launched++;
