            jobs[t].ghin = out + b*16;
            jobs[t].ghlen = nb*16;
            b += nb; launched++;
        }
        post_and_wait(jobs, launched);
    }
    double dt = (now()-t0)/N;
    printf("seq CTR+GHASH threads %d: %.4f s  %.1f MB/s\n", threads, dt, (bytes/1e6)/dt);

    /* Overlapped: process in waves of chunk groups.
       Use 2 threads for CTR and 2 for GHASH, double buffered.
       Split message into many small chunks so pipeline fills.
    */
    int nchunks = 16;
    size_t cblocks = (blocks + nchunks - 1) / nchunks;
    /* ensure alignment already since blocks */
    t0 = now();
    for (int iter = 0; iter < N; iter++) {
        /* For each chunk: 1 thread CTR, then we need ghash after ctr of that chunk.
           Pipeline: start CTR chunk0. When done, start GHASH chunk0 and CTR chunk1 concurrently.
