        /* We'll just use jobs[0] as CTR worker and jobs[1] as GHASH worker, single each.
           To use more, split each wave into 2 CTR + 2 GHASH of previous wave.
        */
        int ctr_threads = threads / 2;
        if (ctr_threads < 1) ctr_threads = 1;
        int gh_threads = threads - ctr_threads;
        size_t wave_blocks = (blocks + 8 - 1) / 8; /* 8 waves */
        /* first wave CTR only */
        size_t b = 0;
        size_t wave = wave_blocks;
