            jobs[t].counter0 = 2;
            bb += nb; launched++;
        }
        post_and_wait(jobs, launched);
        size_t prev_b = b, prev_wave = wave;
        b += wave;

        while (b < blocks) {
            wave = wave_blocks;
            if (b + wave > blocks) wave = blocks - b;
            /* post CTR for current and GHASH for previous concurrently */
            per_c = (wave + ctr_threads - 1) / ctr_threads;
            size_t per_g = (prev_wave + gh_threads - 1) / gh_threads;
            launched = 0;
            bb = b;
            for (int t = 0; t < ctr_threads && bb < b + wave; t++) {
                size_t nb = per_c;
                if (bb + nb > b + wave) nb = b + wave - bb;
                jobs[t].kind = 0;
