                jobs[t].start_block = bb; jobs[t].nblocks = nb;
                memcpy(jobs[t].iv_prefix, iv12, 12);
                jobs[t].counter0 = 2;
                bb += nb; launched++;
            }
            size_t gb = prev_b;
            for (int t = 0; t < gh_threads && gb < prev_b + prev_wave; t++) {
                size_t nb = per_g;
                if (gb + nb > prev_b + prev_wave) nb = prev_b + prev_wave - gb;
                int idx = ctr_threads + t;
                jobs[idx].kind = 1;
                jobs[idx].ghin = out + gb*16;
                jobs[idx].ghlen = nb*16;
                gb += nb; launched++;
            }
            post_and_wait(jobs, launched);
            prev_b = b; prev_wave = wave;
            b += wave;
        }
        /* final ghash */
        size_t per_g = (prev_wave + gh_threads - 1) / gh_threads;
        launched = 0;
        size_t gb = prev_b;
        for (int t = 0; t < gh_threads && gb < prev_b + prev_wave; t++) {
            size_t nb = per_g;
            if (gb + nb > prev_b + prev_wave) nb = prev_b + prev_wave - gb;
            jobs[t].kind = 1;
            jobs[t].ghin = out + gb*16;
            jobs[t].ghlen = nb*16;
            gb += nb; launched++;
        }
        post_and_wait(jobs, launched);
    }
    dt = (now()-t0)/N;
    printf("overlapped threads %d: %.4f s  %.1f MB/s\n", threads, dt, (bytes/1e6)/dt);

    /* correctness of CTR vs single thread */
    unsigned char *out2 = aligned_alloc(64, bytes);
    unsigned char iv[16];
    memcpy(iv, iv12, 12); store_be32(iv+12, 2);
    aesni_ctr32_encrypt_blocks(in, out2, blocks, &key, iv);
    printf("ctr match %d\n", memcmp(out, out2, bytes)==0);

    return 0;
}
