extern void aesni_encrypt(const unsigned char *in, unsigned char *out, const AES_KEY *key);
extern void aesni_ctr32_encrypt_blocks(const unsigned char *in, unsigned char *out,
                                       size_t blocks, const AES_KEY *key, const unsigned char ivec[16]);
extern void gcm_ghash_clmul(uint64_t Xi[2], const void *Htable, const uint8_t *inp, size_t len);

static double now() {
    struct timespec ts; clock_gettime(CLOCK_MONOTONIC, &ts);
    return ts.tv_sec + ts.tv_nsec*1e-9;
}

/* One CTR thread stream + several GHASH threads on completed chunks.
   Simpler microbench: 
   - N producer threads do in-place CTR on their slice (must finish before ghash of that slice)
   - Overlap by splitting each thread's slice into subchunks and ghash previous subchunk on same thread
     WHILE computing next CTR? Same thread can't overlap.
   - 4 CTR threads + 2 GHASH threads: GHASH of completed slices runs while other CTR still going.
     If all CTR finish together, GHASH starts late. 
   Stagger: GHASH threads consume a queue of finished chunks.
*/

#define MAX_T 8
typedef struct {
    unsigned char *buf;
    size_t start_block, nblocks;
    const AES_KEY *key;
    unsigned char iv_prefix[12];
    uint32_t counter0;
    const void *Htable;
    /* queue of finished chunk descriptors for ghash */
    size_t *q_start;
    size_t *q_len;
    int qcap;
    int qh, qt, qcount;
    pthread_mutex_t mu;
    pthread_cond_t cv;
    int producers_done;
    uint64_t Xi[2];
} shared_t;

typedef struct {
    shared_t *S;
    int tid;
    int nproducers;
    size_t my_start, my_blocks;
    int nsub;
} carg;

static void store_be32(unsigned char *p, uint32_t v) {
    p[0]=v>>24; p[1]=v>>16; p[2]=v>>8; p[3]=v;
}

static void *producer(void *arg) {
    carg *c = arg;
    shared_t *S = c->S;
    size_t sub = (c->my_blocks + c->nsub - 1) / c->nsub;
    size_t b = c->my_start;
    size_t remain = c->my_blocks;
    for (int i = 0; i < c->nsub && remain; i++) {
        size_t nb = sub; if (nb > remain) nb = remain;
        unsigned char iv[16];
        memcpy(iv, S->iv_prefix, 12);
        store_be32(iv+12, S->counter0 + (uint32_t)b);
        unsigned char *p = S->buf + b*16;
        aesni_ctr32_encrypt_blocks(p, p, nb, S->key, iv);
        pthread_mutex_lock(&S->mu);
        S->q_start[S->qt] = b;
        S->q_len[S->qt] = nb;
        S->qt = (S->qt + 1) % S->qcap;
        S->qcount++;
        pthread_cond_signal(&S->cv);
        pthread_mutex_unlock(&S->mu);
        b += nb; remain -= nb;
    }
    return NULL;
}

static void *consumer(void *arg) {
    carg *c = arg;
    shared_t *S = c->S;
    uint64_t Xi[2] = {0,0};
    /* each consumer hashes arbitrary chunks; we do NOT combine order here, just throughput */
    for (;;) {
        pthread_mutex_lock(&S->mu);
        while (S->qcount == 0 && !S->producers_done) pthread_cond_wait(&S->cv, &S->mu);
        if (S->qcount == 0 && S->producers_done) { pthread_mutex_unlock(&S->mu); break; }
        size_t b = S->q_start[S->qh];
        size_t nb = S->q_len[S->qh];
        S->qh = (S->qh + 1) % S->qcap;
        S->qcount--;
        pthread_mutex_unlock(&S->mu);
        uint64_t local[2] = {0,0};
        gcm_ghash_clmul(local, S->Htable, S->buf + b*16, nb*16);
        Xi[0] ^= local[0]; Xi[1] ^= local[1]; /* dummy combine */
    }
    c->S->Xi[0] ^= Xi[0];
    return NULL;
}

int main(int argc, char **argv) {
    int nprod = atoi(argv[1]);
    int ncons = atoi(argv[2]);
    int nsub = atoi(argv[3]);
    unsigned char keyb[16]; memset(keyb,1,16);
    AES_KEY key; aesni_set_encrypt_key(keyb,128,&key);
    GCM128_CONTEXT *gctx = CRYPTO_gcm128_new(&key, (block128_f)aesni_encrypt);
    unsigned char iv12[12]; memset(iv12,7,12);
    CRYPTO_gcm128_setiv(gctx, iv12, 12);

    size_t bytes = 60000ull*1024;
    size_t blocks = bytes/16;
    unsigned char *buf = aligned_alloc(64, bytes);
    memset(buf, 0x5a, bytes);

    int qcap = nprod * nsub + 8;
    shared_t S;
    memset(&S, 0, sizeof(S));
    S.buf = buf; S.key = &key; S.Htable = (unsigned char*)gctx + 0x60;
    memcpy(S.iv_prefix, iv12, 12); S.counter0 = 2;
    S.q_start = calloc(qcap, sizeof(size_t));
    S.q_len = calloc(qcap, sizeof(size_t));
    S.qcap = qcap;
    pthread_mutex_init(&S.mu, NULL);
    pthread_cond_init(&S.cv, NULL);

    double t0 = now();
    int N = 4;
    for (int iter = 0; iter < N; iter++) {
        S.qh = S.qt = S.qcount = 0;
        S.producers_done = 0;
        pthread_t pt[16], ct[16];
        carg pc[16], cc[16];
        size_t per = (blocks + nprod - 1) / nprod;
        size_t b = 0;
        for (int t = 0; t < nprod; t++) {
            size_t nb = per; if (b+nb>blocks) nb = blocks-b;
            pc[t].S = &S; pc[t].my_start = b; pc[t].my_blocks = nb; pc[t].nsub = nsub;
            pthread_create(&pt[t], NULL, producer, &pc[t]);
            b += nb;
        }
        for (int t = 0; t < ncons; t++) {
            cc[t].S = &S;
            pthread_create(&ct[t], NULL, consumer, &cc[t]);
        }
        for (int t = 0; t < nprod; t++) pthread_join(pt[t], NULL);
        pthread_mutex_lock(&S.mu);
        S.producers_done = 1;
        pthread_cond_broadcast(&S.cv);
        pthread_mutex_unlock(&S.mu);
        for (int t = 0; t < ncons; t++) pthread_join(ct[t], NULL);
    }
    double dt = (now()-t0)/N;
    printf("prod %d cons %d sub %d: %.4f s %.1f MB/s\n", nprod, ncons, nsub, dt, (bytes/1e6)/dt);
    return 0;
}
