            pthread_mutex_lock(&S.mu);
            int done = S.producers_done && S.qcount==0;
            pthread_mutex_unlock(&S.mu);
            if (done) break;
            struct timespec ts={0, 100000};
            nanosleep(&ts, NULL);
        }
    }

    double t0=now();
    int N=6;
    for (int iter=0; iter<N; iter++) {
        size_t per=(blocks+nprod-1)/nprod; size_t b=0;
        pthread_mutex_lock(&S.mu);
        for (int t=0;t<nprod;t++) {
            size_t nb=per; if(b+nb>blocks) nb=blocks-b;
