    /* Xi is in the byte-swapped internal form used by gcm_ghash_clmul.
       gcm_ghash_clmul expects/produces bswapped Xi (see init which bswaps H).
       To get the GHASH output bytes, bswap Xi back.
    */
    unsigned char ghash_out[16];
    store_be64(ghash_out, Xi[0]);
    store_be64(ghash_out + 8, Xi[1]);

    /* E(K, J0) where J0 = nonce || 1 */
    unsigned char j0[16], ekj0[16], zero[16];
    memcpy(j0, nonce.buf, 12);
    store_be32(j0 + 12, 1);
    memset(zero, 0, 16);
    aesni_ctr32_encrypt_blocks(zero, ekj0, 1, &sched, j0);
    /* wait, ctr32 XORs input with keystream. zero in => keystream out. Good.
       But counter increment: we only ask 1 block so ivec is the counter for that block. Good.
    */

    unsigned char tag[16];
    for (int i = 0; i < 16; i++) tag[i] = ghash_out[i] ^ ekj0[i];

    PyObject *ct_obj = PyBytes_FromStringAndSize((char *)ct_buf, ptlen);
    PyObject *tag_obj = PyBytes_FromStringAndSize((char *)tag, 16);
    CRYPTO_gcm128_release(gctx);
    if (has_aad) PyBuffer_Release(&aad);
    PyBuffer_Release(&key); PyBuffer_Release(&nonce); PyBuffer_Release(&pt);
    return Py_BuildValue("NN", ct_obj, tag_obj);

err_rel:
    if (has_aad) PyBuffer_Release(&aad);
    PyBuffer_Release(&key); PyBuffer_Release(&nonce); PyBuffer_Release(&pt);
    return NULL;
}

static PyMethodDef methods[] = {
    {"encrypt", py_encrypt, METH_VARARGS, ""},
    {NULL, NULL, 0, NULL}
};
static struct PyModuleDef moduledef = {
    PyModuleDef_HEAD_INIT, "gcm_fast", NULL, -1, methods
};
PyMODINIT_FUNC PyInit_gcm_fast(void) { return PyModule_Create(&moduledef); }
