#define PY_SSIZE_T_CLEAN
#include <Python.h>
#include <stdint.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <openssl/aes.h>
#include <openssl/modes.h>

extern void aesni_set_encrypt_key(const unsigned char *userKey, int bits, AES_KEY *key);
extern void aesni_encrypt(const unsigned char *in, unsigned char *out, const AES_KEY *key);
extern void aesni_ctr32_encrypt_blocks(const unsigned char *in, unsigned char *out,
                                       size_t blocks, const AES_KEY *key, const unsigned char ivec[16]);
extern void gcm_ghash_clmul(uint64_t Xi[2], const void *Htable, const uint8_t *inp, size_t len);

#define NTHREADS 4

typedef struct {
    const unsigned char *in;
    unsigned char *out;
    size_t start_block, nblocks;
    const AES_KEY *key;
    unsigned char iv_prefix[12];
    uint32_t counter0;
} job_t;

static void store_be32(unsigned char *p, uint32_t v) {
    p[0] = (unsigned char)(v >> 24);
    p[1] = (unsigned char)(v >> 16);
    p[2] = (unsigned char)(v >> 8);
    p[3] = (unsigned char)v;
}
static void store_be64(unsigned char *p, uint64_t v) {
    for (int i = 7; i >= 0; i--) { p[i] = (unsigned char)v; v >>= 8; }
}

static void *ctr_worker(void *arg) {
    job_t *j = arg;
    if (j->nblocks == 0) return NULL;
    unsigned char iv[16];
    memcpy(iv, j->iv_prefix, 12);
    store_be32(iv + 12, j->counter0 + (uint32_t)j->start_block);
    aesni_ctr32_encrypt_blocks(j->in + j->start_block * 16,
                               j->out + j->start_block * 16,
                               j->nblocks, j->key, iv);
    return NULL;
}

static unsigned char *ct_buf = NULL;
static size_t ct_cap = 0;

static PyObject *py_encrypt(PyObject *self, PyObject *args) {
    Py_buffer key, nonce, pt, aad;
    int has_aad = 0;
    memset(&aad, 0, sizeof(aad));
    if (!PyArg_ParseTuple(args, "y*y*y*|y*", &key, &nonce, &pt, &aad)) {
        PyErr_Clear();
        if (!PyArg_ParseTuple(args, "y*y*y*", &key, &nonce, &pt)) return NULL;
    } else has_aad = 1;

    if (nonce.len != 12 || (key.len != 16 && key.len != 24 && key.len != 32)) {
        PyErr_SetString(PyExc_ValueError, "unsupported key/nonce");
        goto err;
    }

    AES_KEY sched;
    if (aesni_set_encrypt_key((unsigned char *)key.buf, (int)key.len * 8, &sched) != 0) {
        /* aesni_set_encrypt_key returns void actually? AES_set returns int. 
           Our extern says void. Ignore return. */
    }
    /* The symbol is void. Call already done. Rebuild via AES_set if rounds wrong. */
    if (sched.rounds != (key.len == 16 ? 10 : key.len == 24 ? 12 : 14)) {
        /* aesni_set_encrypt_key may use rounds = Nr-1? Earlier probe printed rounds 9 for AES-128.
           OpenSSL AES_set_encrypt_key sets rounds=10. aesni_set_encrypt_key set 9.
           CRYPTO_gcm128_new with aesni_encrypt worked with rounds 9 in the bench, so OK. */
    }

    GCM128_CONTEXT *gctx = CRYPTO_gcm128_new(&sched, (block128_f)aesni_encrypt);
    if (!gctx) { PyErr_NoMemory(); goto err; }
    CRYPTO_gcm128_setiv(gctx, (unsigned char *)nonce.buf, (size_t)nonce.len);
    void *Htable = (unsigned char *)gctx + 0x60;

    size_t ptlen = (size_t)pt.len;
    if (ct_cap < ptlen + 64) {
        free(ct_buf);
        ct_cap = ptlen + 64;
        ct_buf = (unsigned char *)aligned_alloc(64, ct_cap ? ct_cap : 64);
    }
    unsigned char *ct = ct_buf;
    const unsigned char *src = (const unsigned char *)pt.buf;

    size_t full = ptlen / 16;
    size_t rem = ptlen % 16;

    if (full) {
        int nt = NTHREADS;
        if (full < (size_t)nt) nt = (int)full;
        job_t jobs[8];
        pthread_t th[8];
        size_t per = (full + nt - 1) / nt;
        size_t b = 0;
        int launched = 0;
        for (int t = 0; t < nt && b < full; t++) {
            size_t nb = per;
            if (b + nb > full) nb = full - b;
            jobs[t].in = src;
            jobs[t].out = ct;
            jobs[t].start_block = b;
            jobs[t].nblocks = nb;
            jobs[t].key = &sched;
            memcpy(jobs[t].iv_prefix, nonce.buf, 12);
            jobs[t].counter0 = 2;
            pthread_create(&th[t], NULL, ctr_worker, &jobs[t]);
            b += nb;
            launched++;
        }
        for (int t = 0; t < launched; t++) pthread_join(th[t], NULL);
    }
    if (rem) {
        unsigned char iv[16], ks[16], zero[16];
        memcpy(iv, nonce.buf, 12);
        store_be32(iv + 12, 2 + (uint32_t)full);
        memset(zero, 0, 16);
        aesni_ctr32_encrypt_blocks(zero, ks, 1, &sched, iv);
        for (size_t i = 0; i < rem; i++) ct[full * 16 + i] = src[full * 16 + i] ^ ks[i];
    }

    uint64_t Xi[2] = {0, 0};
    if (has_aad && aad.len) {
        size_t alen = (size_t)aad.len;
        size_t afull = alen & ~(size_t)15;
        if (afull) gcm_ghash_clmul(Xi, Htable, (const uint8_t *)aad.buf, afull);
        if (alen & 15) {
            unsigned char pad[16];
            memset(pad, 0, 16);
            memcpy(pad, (unsigned char *)aad.buf + afull, alen & 15);
            gcm_ghash_clmul(Xi, Htable, pad, 16);
        }
    }
    if (ptlen >= 16) gcm_ghash_clmul(Xi, Htable, ct, ptlen & ~(size_t)15);
    if (ptlen & 15) {
        unsigned char pad[16];
        memset(pad, 0, 16);
        memcpy(pad, ct + (ptlen & ~(size_t)15), ptlen & 15);
        gcm_ghash_clmul(Xi, Htable, pad, 16);
    }
    unsigned char lenb[16];
    store_be64(lenb, (uint64_t)(has_aad ? aad.len : 0) * 8);
    store_be64(lenb + 8, (uint64_t)ptlen * 8);
    gcm_ghash_clmul(Xi, Htable, lenb, 16);

    unsigned char ghash_out[16];
    store_be64(ghash_out, Xi[0]);
    store_be64(ghash_out + 8, Xi[1]);

    unsigned char j0[16], ek[16], zero[16];
    memcpy(j0, nonce.buf, 12);
    store_be32(j0 + 12, 1);
    memset(zero, 0, 16);
    aesni_ctr32_encrypt_blocks(zero, ek, 1, &sched, j0);

    unsigned char tag[16];
    for (int i = 0; i < 16; i++) tag[i] = ghash_out[i] ^ ek[i];

    PyObject *ct_obj = PyBytes_FromStringAndSize((char *)ct, (Py_ssize_t)ptlen);
    PyObject *tag_obj = PyBytes_FromStringAndSize((char *)tag, 16);
    CRYPTO_gcm128_release(gctx);
    if (has_aad) PyBuffer_Release(&aad);
    PyBuffer_Release(&key); PyBuffer_Release(&nonce); PyBuffer_Release(&pt);
    return Py_BuildValue("NN", ct_obj, tag_obj);

err:
    if (has_aad) PyBuffer_Release(&aad);
    PyBuffer_Release(&key); PyBuffer_Release(&nonce); PyBuffer_Release(&pt);
    return NULL;
}

static PyMethodDef methods[] = {
    {"encrypt", py_encrypt, METH_VARARGS, ""},
    {NULL, NULL, 0, NULL}
};
static struct PyModuleDef moduledef = {
    PyModuleDef_HEAD_INIT, "gcm_fast", NULL, -1, methods
};
PyMODINIT_FUNC PyInit_gcm_fast(void) { return PyModule_Create(&moduledef); }
EOF
