static int done_flag[NTHREADS];
static pthread_mutex_t done_mu = PTHREAD_MUTEX_INITIALIZER;
static pthread_cond_t done_cv = PTHREAD_COND_INITIALIZER;

static void *worker_fn2(void *arg) {
    worker_t *w = arg;
    int id = (int)(w - workers);
    int seen = 0;
    for (;;) {
        pthread_mutex_lock(&w->mu);
        while (w->go == seen && !w->stop) pthread_cond_wait(&w->cv, &w->mu);
        if (w->stop) { pthread_mutex_unlock(&w->mu); return NULL; }
