static void init_pool(void) {
    if (pool_ready) return;
    for (int i = 0; i < NTHREADS; i++) {
        memset(&workers[i], 0, sizeof(workers[i]));
        pthread_mutex_init(&workers[i].mu, NULL);
        pthread_cond_init(&workers[i].cv, NULL);
        pthread_create(&threads[i], NULL, worker_fn2, &workers[i]);
    }
    pool_ready = 1;
}

static int work_id = 0;

static void parallel_ctr(const unsigned char *in, unsigned char *out, size_t blocks,
                         const AES_KEY *key, const unsigned char iv_prefix[12]) {
    init_pool();
    if (blocks == 0) return;
    int nt = NTHREADS;
    if (blocks < (size_t)nt) nt = (int)blocks;
    size_t per = (blocks + nt - 1) / nt;
    work_id++;
    if (work_id == 0) work_id = 1;
    int id = work_id;
    size_t b = 0;
    for (int t = 0; t < nt; t++) {
        size_t nb = per;
        if (b >= blocks) nb = 0;
        else if (b + nb > blocks) nb = blocks - b;
        pthread_mutex_lock(&workers[t].mu);
        workers[t].in = in;
        workers[t].out = out;
        workers[t].key = key;
        memcpy(workers[t].iv_prefix, iv_prefix, 12);
        workers[t].counter0 = 2;
        workers[t].start_block = b;
        workers[t].nblocks = nb;
        workers[t].go = id;
        pthread_cond_signal(&workers[t].cv);
        pthread_mutex_unlock(&workers[t].mu);
        b += nb;
    }
    /* idle extra threads: still must not wait for them */
    pthread_mutex_lock(&done_mu);
    for (;;) {
        int all = 1;
        for (int t = 0; t < nt; t++) if (done_flag[t] != id) all = 0;
        if (all) break;
        pthread_cond_wait(&done_cv, &done_mu);
    }
    pthread_mutex_unlock(&done_mu);
}

