cat > bench_paths.c << 'EOF'
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>
#include <dlfcn.h>
#include <openssl/sha.h>

static double now() {
    struct timespec t;
    clock_gettime(CLOCK_MONOTONIC, &t);
    return t.tv_sec + t.tv_nsec/1e9;
}

// sha256_block_data_order(SHA256_CTX *ctx, const void *in, size_t num)
typedef void (*block_fn)(void *ctx, const void *in, size_t num);

int main() {
    void *h = dlopen("/usr/local/lib/libcrypto.dylib", RTLD_NOW);
    unsigned char *base_func = (unsigned char*)dlsym(h, "sha256_block_data_order");
    // file offsets: function at 0x246740, avx2 at 0x249a40, avx at 0x248b40, ssse3 at 0x247c80, shaext at 0x247940
    block_fn avx2 = (block_fn)(base_func + (0x249a40 - 0x246740));
    block_fn avx  = (block_fn)(base_func + (0x248b40 - 0x246740));
    block_fn ssse3= (block_fn)(base_func + (0x247c80 - 0x246740));
    block_fn scalar = (block_fn)base_func;

    size_t n = 8*1024*1024;
    unsigned char *buf = malloc(n+64);
    memset(buf, 0x5a, n);

    unsigned char out_ref[32];
    SHA256(buf, n, out_ref);

    struct {
        const char *name;
        block_fn fn;
    } paths[] = {
        {"scalar-dispatch", scalar},
        {"avx2-direct", avx2},
        {"avx-direct", avx},
        {"ssse3-direct", ssse3},
    };

    for (int p = 0; p < 4; p++) {
        // Use SHA256_CTX via public API? We'll manually init and call block then final.
        SHA256_CTX ctx;
        SHA256_Init(&ctx);
        // The block function expects num = number of 64-byte blocks? 
        // From asm: shlq $4, %rdx then leaq (%rsi,%rdx,4) => end = in + num*64. Yes num is block count.
        size_t blocks = n / 64;
        // But SHA256_Update also handles length. If we only call block, we need to set Nh/Nl and then Final.
        // Easier: call block then manually set bit length and call Final? Final pads. 
        // Let's instead just time the block function itself (the bulk), and separately verify by comparing intermediate state after hashing exact blocks via a known method.
        SHA256_Init(&ctx);
        // set bit count as SHA256_Update would: Nl = n<<3
        // We'll replicate by calling Update on 0 bytes after manually processing? messy.
        // Just time the block function; correctness checked by comparing state to a reference ctx that used SHA256_Update.
        paths[p].fn(&ctx, buf, blocks);
        SHA256_CTX ref;
        SHA256_Init(&ref);
        SHA256_Update(&ref, buf, blocks*64);
        int same = memcmp(ctx.h, ref.h, 32)==0;
        // time
        int reps = 3;
        double t0 = now();
        for (int i = 0; i < reps; i++) {
            SHA256_Init(&ctx);
            paths[p].fn(&ctx, buf, blocks);
        }
        double t1 = now();
        printf("%-16s match=%d  %.2f ms  %.1f MB/s\n", paths[p].name, same, (t1-t0)/reps*1000.0, (n*(double)reps/(t1-t0))/1e6);
    }
    return 0;
}
EOF
