{"command":"export TMPDIR="$PWD/tmpcache"
# Persistent thread pool hashing independent chunks, measure throughput of hashing 20MB split across cores
# vs single thread. This tells us if the machine can deliver 3x aggregate.
cat > pool.c << 'EOF'
#include <openssl/sha.h>
#include <pthread.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <stdatomic.h>

#define NTHREADS 6
static double now(){struct timespec t; clock_gettime(CLOCK_MONOTONIC,&t); return t.tv_sec+t.tv_nsec/1e9;}

typedef struct {
    const unsigned char *data;
    size_t len;
    unsigned char out[32];
    atomic_int ready; // 0 idle, 1 work, 2 done, 3 exit
} worker_t;

static worker_t W[NTHREADS];

void *thr(void *arg) {
    worker_t *w = arg;
    for (;;) {
        int r = atomic_load(&w->ready);
        if (r == 3) break;
        if (r == 1) {
            SHA256(w->data, w->len, w->out);
            atomic_store(&w->ready, 2);
        } else {
            // spin
        }
    }
    return NULL;
}

int main() {
    size_t n = 20*1024*1024;
    unsigned char *buf = malloc(n);
    memset(buf, 0x11, n);
    pthread_t th[NTHREADS];
    for (int i = 0; i < NTHREADS; i++) {
        atomic_init(&W[i].ready, 0);
        pthread_create(&th[i], NULL, thr, &W[i]);
    }
    size_t chunk = n / NTHREADS;
    // warmup
    for (int i = 0; i < NTHREADS; i++) {
        W[i].data = buf + i*chunk;
        W[i].len = chunk;
        atomic_store(&W[i].ready, 1);
    }
    for (int i = 0; i < NTHREADS; i++) while (atomic_load(&W[i].ready) != 2) ;
    int reps = 8;
    double t0 = now();
    for (int r = 0; r < reps; r++) {
        for (int i = 0; i < NTHREADS; i++) atomic_store(&W[i].ready, 1);
        for (int i = 0; i < NTHREADS; i++) while (atomic_load(&W[i].ready) != 2) ;
    }
    double t1 = now();
    printf("pool %d: %.2f ms  %.1f MB/s\n", NTHREADS, (t1-t0)/reps*1000, (n*(double)reps/(t1-t0))/1e6);
    for (int i = 0; i < NTHREADS; i++) atomic_store(&W[i].ready, 3);
    for (int i = 0; i < NTHREADS; i++) pthread_join(th[i], NULL);
    return 0;
}
EOF
cc -O2 -o pool pool.c -I/usr/local/include -L/usr/local/lib -lcrypto -lpthread && ./pool"}

