static inline uint64_t rdtsc() {
    unsigned int lo, hi;
    __asm__ volatile("lfence\nrdtsc" : "=a"(lo), "=d"(hi) :: "memory");
    return ((uint64_t)hi << 32) | lo;
}

int main() {
    size_t n = 4*1024*1024;
    unsigned char *buf = malloc(n);
    memset(buf, 0x5a, n);
