    uint64_t c0 = rdtsc();
    int reps = 5;
    for (int i = 0; i < reps; i++) SHA256(buf, n, out);
    uint64_t c1 = rdtsc();
    double cycles = (double)(c1-c0)/reps;
    printf("cycles/byte: %.2f   total cycles %.0f for %zu bytes\n", cycles/n, cycles, n);
    // also time with clock
    struct timespec t0, t1;
    clock_gettime(CLOCK_MONOTONIC, &t0);
    uint64_t r0 = rdtsc();
    for (int i = 0; i < reps; i++) SHA256(buf, n, out);
    uint64_t r1 = rdtsc();
